-- Minimal disposable PostgreSQL fixture. Never run against an application database.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE TABLE public.recursos(id serial PRIMARY KEY,nome text UNIQUE,descricao text);
CREATE TABLE public.installed_integrations(id integer PRIMARY KEY,instance_name text,
 platform_slug text,module_id text,is_active boolean NOT NULL DEFAULT true,app_profile_id text);
CREATE TABLE public.produtos(
 id integer PRIMARY KEY,preco_custo numeric,sku text,nome text,descricao text,categoria_id integer,
 tags text[],atributos jsonb,precificacao jsonb,dados_estoque jsonb,preco_venda numeric,
 estoque_minimo integer,estoque_maximo integer,tipo_material text,unidade_medida_id integer,
 parent_id integer REFERENCES public.produtos(id),status text NOT NULL DEFAULT 'rascunho',
 formato text NOT NULL DEFAULT 'simples',herdar_dados_pai boolean NOT NULL DEFAULT true,
 herdar_bom_pai boolean NOT NULL DEFAULT true);
INSERT INTO public.produtos(id,sku,nome,status,formato,atributos)
 VALUES(9000,'LEGACY_MODEL','Modelo legado','ativo','com_variacao',
        '{"variations_config":[{"name":"Cor","options":["Azul"]}]}'::jsonb);
